      "id": "W7129431440",
      "doi": "10.48550/arxiv.2602.14211",
      "title": "SkillJect: Effectively Automating Skill-Based Prompt Injection for Skill-Enabled Agents",
      "year": 2026,
      "type": "preprint",
      "venue": {
        "name": "arXiv (Cornell University)",
